bool
Macro_ImagePixelMacro::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Macro) << " " << module << endl;

	if (!Macro_ImagePixelDescriptionMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "ImagePixelMacro success after verifying ImagePixelDescriptionMacro " << (success ? "success" : "failure") << endl;
	if (PixelData) PixelData->setUsed();
	if (! verifyType1
			(PixelData,
			"ImagePixelMacro","PixelData",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "ImagePixelMacro success after verifying PixelData " << (success ? "success" : "failure") << endl;

	return success;
}

