bool
Module_MultiFrame::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (NumberOfFrames) NumberOfFrames->setUsed();
	if (! verifyType1
			(NumberOfFrames,
			"MultiFrame","NumberOfFrames",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "MultiFrame success after verifying NumberOfFrames " << (success ? "success" : "failure") << endl;

		if (NumberOfFrames && !NumberOfFrames->verifyNotZero(
			verbose,newformat,log,dict,-1,false)) success=false;

	if (FrameIncrementPointer) FrameIncrementPointer->setUsed();
	if (! verifyType1C
			(FrameIncrementPointer,
			"MultiFrame","FrameIncrementPointer",
			verbose,newformat,log,dict,
			Condition_NotSCMultiFrameOrNumberOfFramesGreaterThanOne, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "MultiFrame success after verifying FrameIncrementPointer " << (success ? "success" : "failure") << endl;

	if (StereoPairsPresent) StereoPairsPresent->setUsed();
	if (! verifyType3
			(StereoPairsPresent,
			"MultiFrame","StereoPairsPresent",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "MultiFrame success after verifying StereoPairsPresent " << (success ? "success" : "failure") << endl;

		if (StereoPairsPresent && !StereoPairsPresent->verifyEnumValues(
			StringValueDescription_YesNoFull,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "MultiFrame success after verifying string enumerated values StereoPairsPresent " << (success ? "success" : "failure") << endl;

	return success;
}

