bool
Macro_FrameAnatomyMacro::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Macro) << " " << module << endl;

	if (FrameAnatomySequence) FrameAnatomySequence->setUsed();
	if (! verifyType1
			(FrameAnatomySequence,
			"FrameAnatomyMacro","FrameAnatomySequence",
			verbose,newformat,log,dict,
			list, 
			1,1)) success=false;
	if (verbose)
		log << "FrameAnatomyMacro success after verifying FrameAnatomySequence " << (success ? "success" : "failure") << endl;
	if (FrameAnatomySequence && strcmp(FrameAnatomySequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=FrameAnatomySequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "FrameAnatomySequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *FrameLaterality = (*list)[TagFromName(FrameLaterality)];
				if (FrameLaterality) FrameLaterality->setUsed();
				if (! verifyType1
						(FrameLaterality,
						"FrameAnatomyMacro","FrameLaterality",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "FrameAnatomyMacro success after verifying FrameLaterality " << (success ? "success" : "failure") << endl;

					if (FrameLaterality && !FrameLaterality->verifyEnumValues(
						StringValueDescription_ImageLaterality,
						verbose,newformat,log,dict,-1)) success=false;
				if (verbose)
					log << "FrameAnatomyMacro success after verifying string enumerated values FrameLaterality " << (success ? "success" : "failure") << endl;

				if (!Macro_GeneralAnatomyMandatoryMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "FrameAnatomyMacro success after verifying GeneralAnatomyMandatoryMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}
	return success;
}

