			Attribute *a = (*list)[TagFromName(LowRRValue)];
			if (a) {
				log << EMsgDCQ("Shall not be present when CardiacSynchronizationTechnique is not PROSPECTIVE or RETROSPECTIVE",a->buildFullPathInInstanceToCurrentAttribute(dict));
			}
