bool
Module_MultiFrameFunctionalGroupsForMFSC::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (SharedFunctionalGroupsSequence) SharedFunctionalGroupsSequence->setUsed();
	if (! verifyType1
			(SharedFunctionalGroupsSequence,
			"MultiFrameFunctionalGroupsForMFSC","SharedFunctionalGroupsSequence",
			verbose,newformat,log,dict,
			list, 
			1,1)) success=false;
	if (verbose)
		log << "MultiFrameFunctionalGroupsForMFSC success after verifying SharedFunctionalGroupsSequence " << (success ? "success" : "failure") << endl;
	if (SharedFunctionalGroupsSequence && strcmp(SharedFunctionalGroupsSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=SharedFunctionalGroupsSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "SharedFunctionalGroupsSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				if (Condition_PixelMeasuresSequenceNotInPerFrameFunctionalGroupSequenceAndPlanePositionSequenceOrPlaneOrientationSequencePresent(list,parentlist,rootlist)) {
				if (!Macro_PixelMeasuresMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "MultiFrameFunctionalGroupsForMFSC success after verifying PixelMeasuresMacro " << (success ? "success" : "failure") << endl;
				if (Condition_PlanePositionSequenceNotInPerFrameFunctionalGroupSequenceAndPixelMeasuresSequenceOrPlaneOrientationSequencePresent(list,parentlist,rootlist)) {
				if (!Macro_PlanePositionMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "MultiFrameFunctionalGroupsForMFSC success after verifying PlanePositionMacro " << (success ? "success" : "failure") << endl;
				if (Condition_PlaneOrientationSequenceNotInPerFrameFunctionalGroupSequenceAndPixelMeasuresSequenceOrPlanePositionSequencePresent(list,parentlist,rootlist)) {
				if (!Macro_PlaneOrientationMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "MultiFrameFunctionalGroupsForMFSC success after verifying PlaneOrientationMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}
	if (PerFrameFunctionalGroupsSequence) PerFrameFunctionalGroupsSequence->setUsed();
	if (! verifyType1
			(PerFrameFunctionalGroupsSequence,
			"MultiFrameFunctionalGroupsForMFSC","PerFrameFunctionalGroupsSequence",
			verbose,newformat,log,dict,
			list, 
			1,VMUNLIMITED)) success=false;
	if (verbose)
		log << "MultiFrameFunctionalGroupsForMFSC success after verifying PerFrameFunctionalGroupsSequence " << (success ? "success" : "failure") << endl;
	if (PerFrameFunctionalGroupsSequence && strcmp(PerFrameFunctionalGroupsSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=PerFrameFunctionalGroupsSequence->getLists(&array)) > 0) {
			if (!allpffgitems) n=1;
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "PerFrameFunctionalGroupsSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				if (Condition_PixelMeasuresSequenceNotInSharedFunctionalGroupSequenceAndPlanePositionSequenceOrPlaneOrientationSequencePresent(list,parentlist,rootlist)) {
				if (!Macro_PixelMeasuresMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "MultiFrameFunctionalGroupsForMFSC success after verifying PixelMeasuresMacro " << (success ? "success" : "failure") << endl;
				if (Condition_PlanePositionSequenceNotInSharedFunctionalGroupSequenceAndPixelMeasuresSequenceOrPlaneOrientationSequencePresent(list,parentlist,rootlist)) {
				if (!Macro_PlanePositionMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "MultiFrameFunctionalGroupsForMFSC success after verifying PlanePositionMacro " << (success ? "success" : "failure") << endl;
				if (Condition_PlaneOrientationSequenceNotInSharedFunctionalGroupSequenceAndPixelMeasuresSequenceOrPlanePositionSequencePresent(list,parentlist,rootlist)) {
				if (!Macro_PlaneOrientationMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "MultiFrameFunctionalGroupsForMFSC success after verifying PlaneOrientationMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}
	return success;
}

