bool
Macro_VOILUTMacro::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Macro) << " " << module << endl;

	if (VOILUTSequence) VOILUTSequence->setUsed();
	if (! verifyType1C
			(VOILUTSequence,
			"VOILUTMacro","VOILUTSequence",
			verbose,newformat,log,dict,
			Condition_MonochromeAndWindowCenterNotPresent, 
			true, 
			list,parentlist,rootlist, 
			1,VMUNLIMITED)) success=false;
	if (verbose)
		log << "VOILUTMacro success after verifying VOILUTSequence " << (success ? "success" : "failure") << endl;
	if (VOILUTSequence && strcmp(VOILUTSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=VOILUTSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "VOILUTSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *LUTDescriptor = (*list)[TagFromName(LUTDescriptor)];
				if (LUTDescriptor) LUTDescriptor->setUsed();
				if (! verifyType1
						(LUTDescriptor,
						"VOILUTMacro","LUTDescriptor",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "VOILUTMacro success after verifying LUTDescriptor " << (success ? "success" : "failure") << endl;


				if (Condition_VOILUTSequenceLUTDescriptorRequiredToBe8Or16(list,parentlist,rootlist)) {
					if (LUTDescriptor && !LUTDescriptor->verifyEnumValues(
						BinaryValueDescription_BitsAre8Or16,
						verbose,newformat,log,dict,2)) success=false;
				}
				if (verbose)
					log << "VOILUTMacro success after verifying binary enumerated values LUTDescriptor " << (success ? "success" : "failure") << endl;

				Attribute *LUTExplanation = (*list)[TagFromName(LUTExplanation)];
				if (LUTExplanation) LUTExplanation->setUsed();
				if (! verifyType3
						(LUTExplanation,
						"VOILUTMacro","LUTExplanation",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "VOILUTMacro success after verifying LUTExplanation " << (success ? "success" : "failure") << endl;

				Attribute *LUTData = (*list)[TagFromName(LUTData)];
				if (LUTData) LUTData->setUsed();
				if (! verifyType1
						(LUTData,
						"VOILUTMacro","LUTData",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "VOILUTMacro success after verifying LUTData " << (success ? "success" : "failure") << endl;

			}
		}
	}
	if (WindowCenter) WindowCenter->setUsed();
	if (! verifyType1C
			(WindowCenter,
			"VOILUTMacro","WindowCenter",
			verbose,newformat,log,dict,
			Condition_MonochromeAndVOILUTSequenceNotPresent, 
			true, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "VOILUTMacro success after verifying WindowCenter " << (success ? "success" : "failure") << endl;

	if (WindowWidth) WindowWidth->setUsed();
	if (! verifyType1C
			(WindowWidth,
			"VOILUTMacro","WindowWidth",
			verbose,newformat,log,dict,
			Condition_WindowCenterPresent, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "VOILUTMacro success after verifying WindowWidth " << (success ? "success" : "failure") << endl;

	if (Condition_WindowCenterPresent(list,parentlist,rootlist)) {
		if (WindowWidth && !WindowWidth->verifyNotZero(
			verbose,newformat,log,dict,-1,false)) success=false;
	}


	if (Condition_WindowWidthIsNegative(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(WindowWidth)];
			if (a) {
				log << EMsgDCQ("Not permitted to be negative",a->buildFullPathInInstanceToValueOfCurrentAttribute(dict,1));
				log << " = <" << (const char *)AttributeValue((*list)[TagFromName(WindowWidth)],"") << ">";
			}
			else {
				log << list->EMsgDCF("Not permitted to be negative","WindowWidth");
			}
		}
		else {
			log << EMsgDCNull() << "Not permitted to be negative - attribute <WindowWidth>";
			log << " = <" << (const char *)AttributeValue((*list)[TagFromName(WindowWidth)],"") << ">";
		}
		log << endl;
	}


	if (Condition_WindowWidthIsLessThanOneAndNotExact(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(WindowWidth)];
			if (a) {
				log << EMsgDCQ("Not permitted to be < 1 unless VOILUTFunction is LINEAR_EXACT or SIGMOID",a->buildFullPathInInstanceToValueOfCurrentAttribute(dict,1));
				log << " = <" << (const char *)AttributeValue((*list)[TagFromName(WindowWidth)],"") << ">";
			}
			else {
				log << list->EMsgDCF("Not permitted to be < 1 unless VOILUTFunction is LINEAR_EXACT or SIGMOID","WindowWidth");
			}
		}
		else {
			log << EMsgDCNull() << "Not permitted to be < 1 unless VOILUTFunction is LINEAR_EXACT or SIGMOID - attribute <WindowWidth>";
			log << " = <" << (const char *)AttributeValue((*list)[TagFromName(WindowWidth)],"") << ">";
		}
		log << endl;
	}


	if (Condition_WindowWidthIsZeroAndSigmoid(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(WindowWidth)];
			if (a) {
				log << EMsgDCQ("Not permitted to be 0 when VOILUTFunction is SIGMOID",a->buildFullPathInInstanceToValueOfCurrentAttribute(dict,1));
				log << " = <" << (const char *)AttributeValue((*list)[TagFromName(WindowWidth)],"") << ">";
			}
			else {
				log << list->EMsgDCF("Not permitted to be 0 when VOILUTFunction is SIGMOID","WindowWidth");
			}
		}
		else {
			log << EMsgDCNull() << "Not permitted to be 0 when VOILUTFunction is SIGMOID - attribute <WindowWidth>";
			log << " = <" << (const char *)AttributeValue((*list)[TagFromName(WindowWidth)],"") << ">";
		}
		log << endl;
	}

	if (WindowCenterWidthExplanation) WindowCenterWidthExplanation->setUsed();
	if (! verifyType3
			(WindowCenterWidthExplanation,
			"VOILUTMacro","WindowCenterWidthExplanation",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "VOILUTMacro success after verifying WindowCenterWidthExplanation " << (success ? "success" : "failure") << endl;

	if (VOILUTFunction) VOILUTFunction->setUsed();
	if (! verifyType3
			(VOILUTFunction,
			"VOILUTMacro","VOILUTFunction",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "VOILUTMacro success after verifying VOILUTFunction " << (success ? "success" : "failure") << endl;

		if (VOILUTFunction) VOILUTFunction->verifyDefinedTerms(
			StringValueDescription_VOILUTFunction,
			verbose,newformat,log,dict,-1);
	if (verbose)
		log << "VOILUTMacro success after verifying string defined terms VOILUTFunction " << (success ? "success" : "failure") << endl;


	if (!Condition_PhotometricInterpretationIsGrayscaleOrAbsent(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(PhotometricInterpretation)];
			if (a) {
				log << WMsgDCQ("VOI LUT Module (WindowCenter and WindowWidth) not appropriate for non-grayscale images",a->buildFullPathInInstanceToValueOfCurrentAttribute(dict,1));
				log << " = <" << (const char *)AttributeValue((*list)[TagFromName(PhotometricInterpretation)],"") << ">";
			}
			else {
				log << list->WMsgDCF("VOI LUT Module (WindowCenter and WindowWidth) not appropriate for non-grayscale images","PhotometricInterpretation");
			}
		}
		else {
			log << WMsgDCNull() << "VOI LUT Module (WindowCenter and WindowWidth) not appropriate for non-grayscale images - attribute <PhotometricInterpretation>";
			log << " = <" << (const char *)AttributeValue((*list)[TagFromName(PhotometricInterpretation)],"") << ">";
		}
		log << endl;
	}

	return success;
}

