bool
Module_CommonInstanceReference::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (ReferencedSeriesSequence) ReferencedSeriesSequence->setUsed();
	if (! verifyType1C
			(ReferencedSeriesSequence,
			"CommonInstanceReference","ReferencedSeriesSequence",
			verbose,newformat,log,dict,
			Condition_StudiesContainingOtherReferencedInstancesSequenceAbsentAndInstanceReferencesInstances, 
			true, 
			list,parentlist,rootlist, 
			1,VMUNLIMITED)) success=false;
	if (verbose)
		log << "CommonInstanceReference success after verifying ReferencedSeriesSequence " << (success ? "success" : "failure") << endl;
	if (ReferencedSeriesSequence && strcmp(ReferencedSeriesSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=ReferencedSeriesSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "ReferencedSeriesSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *SeriesInstanceUID = (*list)[TagFromName(SeriesInstanceUID)];
				if (SeriesInstanceUID) SeriesInstanceUID->setUsed();
				if (! verifyType1
						(SeriesInstanceUID,
						"CommonInstanceReference","SeriesInstanceUID",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "CommonInstanceReference success after verifying SeriesInstanceUID " << (success ? "success" : "failure") << endl;


				if (Condition_StudyInstanceUIDIsPresent(list,parentlist,rootlist)) {
					if (newformat) {
			Attribute *a = (*list)[TagFromName(StudyInstanceUID)];
			if (a) {
				log << EMsgDCQ("StudyInstanceUID should not be present in ReferencedSeriesSequence in CommonInstanceReference Module - use StudiesContainingOtherReferencedInstancesSequence if not the same Study",a->buildFullPathInInstanceToCurrentAttribute(dict));
			}
			else {
				log << list->EMsgDCF("StudyInstanceUID should not be present in ReferencedSeriesSequence in CommonInstanceReference Module - use StudiesContainingOtherReferencedInstancesSequence if not the same Study","StudyInstanceUID");
			}
		}
		else {
			log << EMsgDCNull() << "StudyInstanceUID should not be present in ReferencedSeriesSequence in CommonInstanceReference Module - use StudiesContainingOtherReferencedInstancesSequence if not the same Study - attribute <StudyInstanceUID>";
		}
		log << endl;
				}

	Attribute *ReferencedInstanceSequence = (*list)[TagFromName(ReferencedInstanceSequence)];
				if (ReferencedInstanceSequence) ReferencedInstanceSequence->setUsed();
				if (! verifyType1
						(ReferencedInstanceSequence,
						"CommonInstanceReference","ReferencedInstanceSequence",
						verbose,newformat,log,dict,
									list, 
						1,VMUNLIMITED)) success=false;
				if (verbose)
					log << "CommonInstanceReference success after verifying ReferencedInstanceSequence " << (success ? "success" : "failure") << endl;
				if (ReferencedInstanceSequence && strcmp(ReferencedInstanceSequence->getVR(),"SQ") == 0) {
					AttributeList **array;
					int n;
					if ((n=ReferencedInstanceSequence->getLists(&array)) > 0) {
									int i; for (i=0; i<n; ++i) {
							if (verbose)
								log << "ReferencedInstanceSequence" << " item [" << (i+1) << "]" << endl;
							AttributeList *parentlist=list;
							AttributeList *list=array[i];
							if (!Macro_SOPInstanceReferenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

							if (verbose)
								log << "CommonInstanceReference success after verifying SOPInstanceReferenceMacro " << (success ? "success" : "failure") << endl;
						}
					}
				}
			}
		}
	}

	if (Condition_ReferencedSeriesSequencePresentAndInstanceDoesNotReferencesInstances(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(ReferencedSeriesSequence)];
			if (a) {
				log << EMsgDCQ("ReferencedSeriesSequence present but Instance does not reference Instances",a->buildFullPathInInstanceToCurrentAttribute(dict));
			}
			else {
				log << list->EMsgDCF("ReferencedSeriesSequence present but Instance does not reference Instances","ReferencedSeriesSequence");
			}
		}
		else {
			log << EMsgDCNull() << "ReferencedSeriesSequence present but Instance does not reference Instances - attribute <ReferencedSeriesSequence>";
		}
		log << endl;
	}

	if (StudiesContainingOtherReferencedInstancesSequence) StudiesContainingOtherReferencedInstancesSequence->setUsed();
	if (! verifyType1C
			(StudiesContainingOtherReferencedInstancesSequence,
			"CommonInstanceReference","StudiesContainingOtherReferencedInstancesSequence",
			verbose,newformat,log,dict,
			Condition_ReferencedSeriesSequenceAbsentAndInstanceReferencesInstances, 
			true, 
			list,parentlist,rootlist, 
			1,VMUNLIMITED)) success=false;
	if (verbose)
		log << "CommonInstanceReference success after verifying StudiesContainingOtherReferencedInstancesSequence " << (success ? "success" : "failure") << endl;
	if (StudiesContainingOtherReferencedInstancesSequence && strcmp(StudiesContainingOtherReferencedInstancesSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=StudiesContainingOtherReferencedInstancesSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "StudiesContainingOtherReferencedInstancesSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *StudyInstanceUID = (*list)[TagFromName(StudyInstanceUID)];
				if (StudyInstanceUID) StudyInstanceUID->setUsed();
				if (! verifyType1
						(StudyInstanceUID,
						"CommonInstanceReference","StudyInstanceUID",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "CommonInstanceReference success after verifying StudyInstanceUID " << (success ? "success" : "failure") << endl;

				if (!Macro_SeriesAndInstanceReferenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "CommonInstanceReference success after verifying SeriesAndInstanceReferenceMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}

	if (Condition_StudiesContainingOtherReferencedInstancesSequencePresentAndInstanceDoesNotReferencesInstances(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(StudiesContainingOtherReferencedInstancesSequence)];
			if (a) {
				log << EMsgDCQ("StudiesContainingOtherReferencedInstancesSequence present but Instance does not reference Instances",a->buildFullPathInInstanceToCurrentAttribute(dict));
			}
			else {
				log << list->EMsgDCF("StudiesContainingOtherReferencedInstancesSequence present but Instance does not reference Instances","StudiesContainingOtherReferencedInstancesSequence");
			}
		}
		else {
			log << EMsgDCNull() << "StudiesContainingOtherReferencedInstancesSequence present but Instance does not reference Instances - attribute <StudiesContainingOtherReferencedInstancesSequence>";
		}
		log << endl;
	}

	return success;
}

