bool
Module_SpatialFiducialsSeries::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (Modality) Modality->setUsed();
	if (! verifyType1
			(Modality,
			"SpatialFiducialsSeries","Modality",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "SpatialFiducialsSeries success after verifying Modality " << (success ? "success" : "failure") << endl;

		if (Modality && !Modality->verifyEnumValues(
			StringValueDescription_FIDModality,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "SpatialFiducialsSeries success after verifying string enumerated values Modality " << (success ? "success" : "failure") << endl;

	return success;
}

