				if (verbose)
					log << "PETIsotope success after verifying RadiopharmaceuticalRoute " << (success ? "success" : "failure") << endl;

	Attribute *AdministrationRouteCodeSequence = (*list)[TagFromName(AdministrationRouteCodeSequence)];
