bool
Module_PETMultigatedAcquisition::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (BeatRejectionFlag) BeatRejectionFlag->setUsed();
	if (! verifyType2
			(BeatRejectionFlag,
			"PETMultigatedAcquisition","BeatRejectionFlag",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying BeatRejectionFlag " << (success ? "success" : "failure") << endl;

		if (BeatRejectionFlag && !BeatRejectionFlag->verifyEnumValues(
			StringValueDescription_YesNoLetter,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying string enumerated values BeatRejectionFlag " << (success ? "success" : "failure") << endl;

	if (TriggerSourceOrType) TriggerSourceOrType->setUsed();
	if (! verifyType3
			(TriggerSourceOrType,
			"PETMultigatedAcquisition","TriggerSourceOrType",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying TriggerSourceOrType " << (success ? "success" : "failure") << endl;

		if (TriggerSourceOrType) TriggerSourceOrType->verifyDefinedTerms(
			StringValueDescription_EKG,
			verbose,newformat,log,dict,-1);
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying string defined terms TriggerSourceOrType " << (success ? "success" : "failure") << endl;

	if (PVCRejection) PVCRejection->setUsed();
	if (! verifyType3
			(PVCRejection,
			"PETMultigatedAcquisition","PVCRejection",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying PVCRejection " << (success ? "success" : "failure") << endl;

	if (SkipBeats) SkipBeats->setUsed();
	if (! verifyType3
			(SkipBeats,
			"PETMultigatedAcquisition","SkipBeats",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying SkipBeats " << (success ? "success" : "failure") << endl;

	if (HeartRate) HeartRate->setUsed();
	if (! verifyType3
			(HeartRate,
			"PETMultigatedAcquisition","HeartRate",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying HeartRate " << (success ? "success" : "failure") << endl;

	if (CardiacFramingType) CardiacFramingType->setUsed();
	if (! verifyType3
			(CardiacFramingType,
			"PETMultigatedAcquisition","CardiacFramingType",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying CardiacFramingType " << (success ? "success" : "failure") << endl;

		if (CardiacFramingType) CardiacFramingType->verifyDefinedTerms(
			StringValueDescription_CardiacFramingType,
			verbose,newformat,log,dict,-1);
	if (verbose)
		log << "PETMultigatedAcquisition success after verifying string defined terms CardiacFramingType " << (success ? "success" : "failure") << endl;

	return success;
}

