bool
Module_Approval::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (ApprovalStatus) ApprovalStatus->setUsed();
	if (! verifyType1
			(ApprovalStatus,
			"Approval","ApprovalStatus",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "Approval success after verifying ApprovalStatus " << (success ? "success" : "failure") << endl;

		if (ApprovalStatus && !ApprovalStatus->verifyEnumValues(
			StringValueDescription_ApprovalStatus,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "Approval success after verifying string enumerated values ApprovalStatus " << (success ? "success" : "failure") << endl;

	if (ReviewDate) ReviewDate->setUsed();
	if (! verifyType2C
			(ReviewDate,
			"Approval","ReviewDate",
			verbose,newformat,log,dict,
			Condition_ApprovalStatusApprovedOrRejected, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "Approval success after verifying ReviewDate " << (success ? "success" : "failure") << endl;

	if (ReviewTime) ReviewTime->setUsed();
	if (! verifyType2C
			(ReviewTime,
			"Approval","ReviewTime",
			verbose,newformat,log,dict,
			Condition_ApprovalStatusApprovedOrRejected, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "Approval success after verifying ReviewTime " << (success ? "success" : "failure") << endl;

	if (ReviewerName) ReviewerName->setUsed();
	if (! verifyType2C
			(ReviewerName,
			"Approval","ReviewerName",
			verbose,newformat,log,dict,
			Condition_ApprovalStatusApprovedOrRejected, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "Approval success after verifying ReviewerName " << (success ? "success" : "failure") << endl;

	return success;
}

