bool
Module_DXSeries::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (Modality) Modality->setUsed();
	if (! verifyType1
			(Modality,
			"DXSeries","Modality",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "DXSeries success after verifying Modality " << (success ? "success" : "failure") << endl;

		if (Modality && !Modality->verifyEnumValues(
			StringValueDescription_DXModality,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "DXSeries success after verifying string enumerated values Modality " << (success ? "success" : "failure") << endl;

	if (ReferencedPerformedProcedureStepSequence) ReferencedPerformedProcedureStepSequence->setUsed();
	if (! verifyType1C
			(ReferencedPerformedProcedureStepSequence,
			"DXSeries","ReferencedPerformedProcedureStepSequence",
			verbose,newformat,log,dict,
			Condition_SeriesNeedReferencedPerformedProcedureStepSequence, 
			false, 
			list,parentlist,rootlist, 
			1,1)) success=false;
	if (verbose)
		log << "DXSeries success after verifying ReferencedPerformedProcedureStepSequence " << (success ? "success" : "failure") << endl;
	if (ReferencedPerformedProcedureStepSequence && strcmp(ReferencedPerformedProcedureStepSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=ReferencedPerformedProcedureStepSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "ReferencedPerformedProcedureStepSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				if (!Macro_SOPInstanceReferenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "DXSeries success after verifying SOPInstanceReferenceMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}
	if (PresentationIntentType) PresentationIntentType->setUsed();
	if (! verifyType1
			(PresentationIntentType,
			"DXSeries","PresentationIntentType",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "DXSeries success after verifying PresentationIntentType " << (success ? "success" : "failure") << endl;

		if (PresentationIntentType && !PresentationIntentType->verifyEnumValues(
			StringValueDescription_PresentationIntentType,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "DXSeries success after verifying string enumerated values PresentationIntentType " << (success ? "success" : "failure") << endl;


	if (Condition_IsForProcessingSOPClass(list,parentlist,rootlist)) {
		if (PresentationIntentType && !PresentationIntentType->verifyEnumValues(
			StringValueDescription_ForProcessing,
			verbose,newformat,log,dict,-1)) success=false;
	}
	if (verbose)
		log << "DXSeries success after verifying string enumerated values PresentationIntentType " << (success ? "success" : "failure") << endl;


	if (Condition_IsForPresentationSOPClass(list,parentlist,rootlist)) {
		if (PresentationIntentType && !PresentationIntentType->verifyEnumValues(
			StringValueDescription_ForPresentation,
			verbose,newformat,log,dict,-1)) success=false;
	}
	if (verbose)
		log << "DXSeries success after verifying string enumerated values PresentationIntentType " << (success ? "success" : "failure") << endl;

	return success;
}

