	if (verbose)
		log << "DXDetector success after verifying FieldOfViewOrigin " << (success ? "success" : "failure") << endl;

	if (FieldOfViewRotation) FieldOfViewRotation->setUsed();
	if (! verifyType1C
			(FieldOfViewRotation,
			"DXDetector","FieldOfViewRotation",
			verbose,newformat,log,dict,
			Condition_FieldOfViewHorizontalFlipPresent, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
