bool
Module_BreastView::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (ImageType) ImageType->setUsed();
	if (! verifyType1
			(ImageType,
			"BreastView","ImageType",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "BreastView success after verifying ImageType " << (success ? "success" : "failure") << endl;

		if (ImageType) ImageType->verifyDefinedTerms(
			StringValueDescription_CommonEnhancedImageAndFrameType3AndBreastTomoImageAndFrameType3,
			verbose,newformat,log,dict,2);
	if (verbose)
		log << "BreastView success after verifying string defined terms ImageType " << (success ? "success" : "failure") << endl;


		if (ImageType) ImageType->verifyDefinedTerms(
			StringValueDescription_BreastTomoImageAndFrameType4,
			verbose,newformat,log,dict,3);
	if (verbose)
		log << "BreastView success after verifying string defined terms ImageType " << (success ? "success" : "failure") << endl;


		if (ImageType) ImageType->verifyDefinedTerms(
			StringValueDescription_BreastTomoImageAndFrameType5,
			verbose,newformat,log,dict,4);
	if (verbose)
		log << "BreastView success after verifying string defined terms ImageType " << (success ? "success" : "failure") << endl;

	if (ViewCodeSequence) ViewCodeSequence->setUsed();
	if (! verifyType1
			(ViewCodeSequence,
			"BreastView","ViewCodeSequence",
			verbose,newformat,log,dict,
			list, 
			1,1)) success=false;
	if (verbose)
		log << "BreastView success after verifying ViewCodeSequence " << (success ? "success" : "failure") << endl;
	if (ViewCodeSequence && strcmp(ViewCodeSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=ViewCodeSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "ViewCodeSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				if (!Macro_CodeSequenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "BreastView success after verifying CodeSequenceMacro " << (success ? "success" : "failure") << endl;
	Attribute *ViewModifierCodeSequence = (*list)[TagFromName(ViewModifierCodeSequence)];
				if (ViewModifierCodeSequence) ViewModifierCodeSequence->setUsed();
				if (! verifyType2
						(ViewModifierCodeSequence,
						"BreastView","ViewModifierCodeSequence",
						verbose,newformat,log,dict,
									list, 
						0,VMUNLIMITED)) success=false;
				if (verbose)
					log << "BreastView success after verifying ViewModifierCodeSequence " << (success ? "success" : "failure") << endl;
				if (ViewModifierCodeSequence && strcmp(ViewModifierCodeSequence->getVR(),"SQ") == 0) {
					AttributeList **array;
					int n;
					if ((n=ViewModifierCodeSequence->getLists(&array)) > 0) {
									int i; for (i=0; i<n; ++i) {
							if (verbose)
								log << "ViewModifierCodeSequence" << " item [" << (i+1) << "]" << endl;
							AttributeList *parentlist=list;
							AttributeList *list=array[i];
							if (!Macro_CodeSequenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

							if (verbose)
								log << "BreastView success after verifying CodeSequenceMacro " << (success ? "success" : "failure") << endl;
						}
					}
				}
			}
		}
	}
	if (BreastImplantPresent) BreastImplantPresent->setUsed();
	if (! verifyType1C
			(BreastImplantPresent,
			"BreastView","BreastImplantPresent",
			verbose,newformat,log,dict,
			Condition_ModalityIsMG, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "BreastView success after verifying BreastImplantPresent " << (success ? "success" : "failure") << endl;

	if (Condition_ModalityIsMG(list,parentlist,rootlist)) {
		if (BreastImplantPresent && !BreastImplantPresent->verifyEnumValues(
			StringValueDescription_YesNoFull,
			verbose,newformat,log,dict,-1)) success=false;
	}
	if (verbose)
		log << "BreastView success after verifying string enumerated values BreastImplantPresent " << (success ? "success" : "failure") << endl;

	if (PartialView) PartialView->setUsed();
	if (! verifyType3
			(PartialView,
			"BreastView","PartialView",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "BreastView success after verifying PartialView " << (success ? "success" : "failure") << endl;

		if (PartialView && !PartialView->verifyEnumValues(
			StringValueDescription_YesNoFull,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "BreastView success after verifying string enumerated values PartialView " << (success ? "success" : "failure") << endl;


	if (Condition_ViewModifierCodeSequenceIsMagnificationOrSpotCompression(list,parentlist,rootlist)) {
		if (PartialView && !PartialView->verifyEnumValues(
			StringValueDescription_NoFull,
			verbose,newformat,log,dict,-1)) success=false;
	}
	if (verbose)
		log << "BreastView success after verifying string enumerated values PartialView " << (success ? "success" : "failure") << endl;

	if (PartialViewCodeSequence) PartialViewCodeSequence->setUsed();
	if (! verifyType1C
			(PartialViewCodeSequence,
			"BreastView","PartialViewCodeSequence",
			verbose,newformat,log,dict,
			Condition_PartialViewIsYes, 
			false, 
			list,parentlist,rootlist, 
			1,2)) success=false;
	if (verbose)
		log << "BreastView success after verifying PartialViewCodeSequence " << (success ? "success" : "failure") << endl;
	if (PartialViewCodeSequence && strcmp(PartialViewCodeSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=PartialViewCodeSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "PartialViewCodeSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				if (!Macro_CodeSequenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "BreastView success after verifying CodeSequenceMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}
	return success;
}

