bool
Module_OphthalmicTomographyAcquisitionParameters::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (AxialLengthOfTheEye) AxialLengthOfTheEye->setUsed();
	if (! verifyType2
			(AxialLengthOfTheEye,
			"OphthalmicTomographyAcquisitionParameters","AxialLengthOfTheEye",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "OphthalmicTomographyAcquisitionParameters success after verifying AxialLengthOfTheEye " << (success ? "success" : "failure") << endl;

		if (AxialLengthOfTheEye && !AxialLengthOfTheEye->verifyNotZero(
			verbose,newformat,log,dict,-1,true)) success=false;

	if (HorizontalFieldOfView) HorizontalFieldOfView->setUsed();
	if (! verifyType2
			(HorizontalFieldOfView,
			"OphthalmicTomographyAcquisitionParameters","HorizontalFieldOfView",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "OphthalmicTomographyAcquisitionParameters success after verifying HorizontalFieldOfView " << (success ? "success" : "failure") << endl;

		if (HorizontalFieldOfView && !HorizontalFieldOfView->verifyNotZero(
			verbose,newformat,log,dict,-1,true)) success=false;

	if (!Macro_OphthalmicAcquisitionParametersMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "OphthalmicTomographyAcquisitionParameters success after verifying OphthalmicAcquisitionParametersMacro " << (success ? "success" : "failure") << endl;
	return success;
}

