					log << "WaveformIdentification success after verifying SOPInstanceReferenceMacro " << (success ? "success" : "failure") << endl;
	Attribute *PurposeOfReferenceCodeSequence = (*list)[TagFromName(PurposeOfReferenceCodeSequence)];
				if (PurposeOfReferenceCodeSequence) PurposeOfReferenceCodeSequence->setUsed();
