				if (!Macro_SOPInstanceReferenceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "ImageReferenceMacro success after verifying SOPInstanceReferenceMacro " << (success ? "success" : "failure") << endl;
				Attribute *ReferencedFrameNumber = (*list)[TagFromName(ReferencedFrameNumber)];
				if (ReferencedFrameNumber) ReferencedFrameNumber->setUsed();
