bool
Macro_DocumentRelationshipMacro::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Macro) << " " << module << endl;

	if (ObservationDateTime) ObservationDateTime->setUsed();
	if (! verifyType1C
			(ObservationDateTime,
			"DocumentRelationshipMacro","ObservationDateTime",
			verbose,newformat,log,dict,
			0, 
			false, 
			list,parentlist,rootlist, 
			0,0)) success=false;
	if (verbose)
		log << "DocumentRelationshipMacro success after verifying ObservationDateTime " << (success ? "success" : "failure") << endl;

	if (ObservationUID) ObservationUID->setUsed();
	if (! verifyType3
			(ObservationUID,
			"DocumentRelationshipMacro","ObservationUID",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "DocumentRelationshipMacro success after verifying ObservationUID " << (success ? "success" : "failure") << endl;

	if (ContentSequence) ContentSequence->setUsed();
	if (! verifyType1C
			(ContentSequence,
			"DocumentRelationshipMacro","ContentSequence",
			verbose,newformat,log,dict,
			0, 
			false, 
			list,parentlist,rootlist, 
			1,VMUNLIMITED)) success=false;
	if (verbose)
		log << "DocumentRelationshipMacro success after verifying ContentSequence " << (success ? "success" : "failure") << endl;
	if (ContentSequence && strcmp(ContentSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=ContentSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "ContentSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *RelationshipType = (*list)[TagFromName(RelationshipType)];
				if (RelationshipType) RelationshipType->setUsed();
				if (! verifyType1
						(RelationshipType,
						"DocumentRelationshipMacro","RelationshipType",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "DocumentRelationshipMacro success after verifying RelationshipType " << (success ? "success" : "failure") << endl;

					if (RelationshipType) RelationshipType->verifyDefinedTerms(
						StringValueDescription_SRRelationshipType,
						verbose,newformat,log,dict,-1);
				if (verbose)
					log << "DocumentRelationshipMacro success after verifying string defined terms RelationshipType " << (success ? "success" : "failure") << endl;

				if (Condition_RelationshipByValue(list,parentlist,rootlist)) {
				if (!Macro_DocumentRelationshipMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "DocumentRelationshipMacro success after verifying DocumentRelationshipMacro " << (success ? "success" : "failure") << endl;
				if (Condition_RelationshipByValue(list,parentlist,rootlist)) {
				if (!Macro_DocumentContentMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;
				}

				if (verbose)
					log << "DocumentRelationshipMacro success after verifying DocumentContentMacro " << (success ? "success" : "failure") << endl;
				Attribute *ReferencedContentItemIdentifier = (*list)[TagFromName(ReferencedContentItemIdentifier)];
				if (ReferencedContentItemIdentifier) ReferencedContentItemIdentifier->setUsed();
				if (! verifyType1C
						(ReferencedContentItemIdentifier,
						"DocumentRelationshipMacro","ReferencedContentItemIdentifier",
						verbose,newformat,log,dict,
						Condition_RelationshipByReference, 
						false, 
						list,parentlist,rootlist, 
						0,0)) success=false;
				if (verbose)
					log << "DocumentRelationshipMacro success after verifying ReferencedContentItemIdentifier " << (success ? "success" : "failure") << endl;

				if (Condition_RelationshipByReference(list,parentlist,rootlist)) {
					if (ReferencedContentItemIdentifier && !ReferencedContentItemIdentifier->verifyNotZero(
						verbose,newformat,log,dict,-1,false)) success=false;
				}

			}
		}
	}
	return success;
}

