bool
Module_SRDocumentContent::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (!Macro_DocumentContentMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "SRDocumentContent success after verifying DocumentContentMacro " << (success ? "success" : "failure") << endl;

	if (Condition_ConceptNameCodeSequenceNotPresent(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(ConceptNameCodeSequence)];
			if (a) {
				log << EMsgDCQ("ConceptNameCodeSequence is required for root content item (in top level dataset)",a->buildFullPathInInstanceToCurrentAttribute(dict));
			}
			else {
				log << list->EMsgDCF("ConceptNameCodeSequence is required for root content item (in top level dataset)","ConceptNameCodeSequence");
			}
		}
		else {
			log << EMsgDCNull() << "ConceptNameCodeSequence is required for root content item (in top level dataset) - attribute <ConceptNameCodeSequence>";
		}
		log << endl;
	}

	if (!Macro_DocumentRelationshipMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "SRDocumentContent success after verifying DocumentRelationshipMacro " << (success ? "success" : "failure") << endl;
	return success;
}

