bool
Module_BitmapDisplayShutter::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (ShutterShape) ShutterShape->setUsed();
	if (! verifyType1
			(ShutterShape,
			"BitmapDisplayShutter","ShutterShape",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "BitmapDisplayShutter success after verifying ShutterShape " << (success ? "success" : "failure") << endl;

		if (ShutterShape && !ShutterShape->verifyEnumValues(
			StringValueDescription_BitmapShutterShape,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "BitmapDisplayShutter success after verifying string enumerated values ShutterShape " << (success ? "success" : "failure") << endl;

	if (ShutterOverlayGroup) ShutterOverlayGroup->setUsed();
	if (! verifyType1
			(ShutterOverlayGroup,
			"BitmapDisplayShutter","ShutterOverlayGroup",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "BitmapDisplayShutter success after verifying ShutterOverlayGroup " << (success ? "success" : "failure") << endl;

		if (ShutterOverlayGroup && !ShutterOverlayGroup->verifyEnumValues(
			BinaryValueDescription_AllPossibleOverlayGroups,
			verbose,newformat,log,dict,-1)) success=false;
	if (verbose)
		log << "BitmapDisplayShutter success after verifying binary enumerated values ShutterOverlayGroup " << (success ? "success" : "failure") << endl;

	if (ShutterPresentationValue) ShutterPresentationValue->setUsed();
	if (! verifyType1
			(ShutterPresentationValue,
			"BitmapDisplayShutter","ShutterPresentationValue",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "BitmapDisplayShutter success after verifying ShutterPresentationValue " << (success ? "success" : "failure") << endl;

	if (ShutterPresentationColorCIELabValue) ShutterPresentationColorCIELabValue->setUsed();
	if (! verifyType3
			(ShutterPresentationColorCIELabValue,
			"BitmapDisplayShutter","ShutterPresentationColorCIELabValue",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "BitmapDisplayShutter success after verifying ShutterPresentationColorCIELabValue " << (success ? "success" : "failure") << endl;

	return success;
}

