bool
Module_ICCProfile::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (ICCProfile) ICCProfile->setUsed();
	if (! verifyType1
			(ICCProfile,
			"ICCProfile","ICCProfile",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "ICCProfile success after verifying ICCProfile " << (success ? "success" : "failure") << endl;


	if (Condition_UnwantedOpticalPathAndICCProfileModules(list,parentlist,rootlist)) {
		if (newformat) {
			Attribute *a = (*list)[TagFromName(ICCProfile)];
			if (a) {
				log << EMsgDCQ("ICC Profile Module shall not be present for VL Microscopic Image IOD or VL Slide-Coordinates Microscopic Image IOD when Optical Path Module is present",a->buildFullPathInInstanceToCurrentAttribute(dict));
			}
			else {
				log << list->EMsgDCF("ICC Profile Module shall not be present for VL Microscopic Image IOD or VL Slide-Coordinates Microscopic Image IOD when Optical Path Module is present","ICCProfile");
			}
		}
		else {
			log << EMsgDCNull() << "ICC Profile Module shall not be present for VL Microscopic Image IOD or VL Slide-Coordinates Microscopic Image IOD when Optical Path Module is present - attribute <ICCProfile>";
		}
		log << endl;
	}

	if (ColorSpace) ColorSpace->setUsed();
	if (! verifyType3
			(ColorSpace,
			"ICCProfile","ColorSpace",
			verbose,newformat,log,dict,
			list, 
			0,0)) success=false;
	if (verbose)
		log << "ICCProfile success after verifying ColorSpace " << (success ? "success" : "failure") << endl;

	return success;
}

