bool
Module_ColorPaletteDefinition::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (!Macro_ContentIdentificationMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "ColorPaletteDefinition success after verifying ContentIdentificationMacro " << (success ? "success" : "failure") << endl;
	return success;
}

