bool
Macro_FunctionalMRMacro::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Macro) << " " << module << endl;

	if (FunctionalMRSequence) FunctionalMRSequence->setUsed();
	if (! verifyType1
			(FunctionalMRSequence,
			"FunctionalMRMacro","FunctionalMRSequence",
			verbose,newformat,log,dict,
			list, 
			1,1)) success=false;
	if (verbose)
		log << "FunctionalMRMacro success after verifying FunctionalMRSequence " << (success ? "success" : "failure") << endl;
	if (FunctionalMRSequence && strcmp(FunctionalMRSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=FunctionalMRSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "FunctionalMRSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *SettlingPhaseFrame = (*list)[TagFromName(SettlingPhaseFrame)];
				if (SettlingPhaseFrame) SettlingPhaseFrame->setUsed();
				if (! verifyType1C
						(SettlingPhaseFrame,
						"FunctionalMRMacro","SettlingPhaseFrame",
						verbose,newformat,log,dict,
						Condition_FunctionalSettlingPhaseFramesPresentIsYes, 
						false, 
						list,parentlist,rootlist, 
						0,0)) success=false;
				if (verbose)
					log << "FunctionalMRMacro success after verifying SettlingPhaseFrame " << (success ? "success" : "failure") << endl;

				if (Condition_FunctionalSettlingPhaseFramesPresentIsYes(list,parentlist,rootlist)) {
					if (SettlingPhaseFrame && !SettlingPhaseFrame->verifyEnumValues(
						StringValueDescription_YesNoFull,
						verbose,newformat,log,dict,-1)) success=false;
				}
				if (verbose)
					log << "FunctionalMRMacro success after verifying string enumerated values SettlingPhaseFrame " << (success ? "success" : "failure") << endl;

				Attribute *FunctionalSyncPulse = (*list)[TagFromName(FunctionalSyncPulse)];
				if (FunctionalSyncPulse) FunctionalSyncPulse->setUsed();
				if (! verifyType1
						(FunctionalSyncPulse,
						"FunctionalMRMacro","FunctionalSyncPulse",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "FunctionalMRMacro success after verifying FunctionalSyncPulse " << (success ? "success" : "failure") << endl;

			}
		}
	}
	return success;
}

