bool
Module_MultienergyCTImage::verify(AttributeList *list,AttributeList *parentlist,AttributeList *rootlist,bool verbose,bool newformat,bool allpffgitems,TextOutputStream& log,ElementDictionary *dict) const
{
	(void)module;  // Quiets compiler in case module empty
	(void)list;
	(void)verbose;
	(void)log;
	(void)dict;
	Assert(list);
	Assert(dict);

	bool success=true;

	if (verbose)
		log << MMsgDC(Verifying) << " " << MMsgDC(Module) << " " << module << endl;

	if (MultienergyCTAcquisitionSequence) MultienergyCTAcquisitionSequence->setUsed();
	if (! verifyType1
			(MultienergyCTAcquisitionSequence,
			"MultienergyCTImage","MultienergyCTAcquisitionSequence",
			verbose,newformat,log,dict,
			list, 
			1,1)) success=false;
	if (verbose)
		log << "MultienergyCTImage success after verifying MultienergyCTAcquisitionSequence " << (success ? "success" : "failure") << endl;
	if (MultienergyCTAcquisitionSequence && strcmp(MultienergyCTAcquisitionSequence->getVR(),"SQ") == 0) {
		AttributeList **array;
		int n;
		if ((n=MultienergyCTAcquisitionSequence->getLists(&array)) > 0) {
			int i; for (i=0; i<n; ++i) {
				if (verbose)
					log << "MultienergyCTAcquisitionSequence" << " item [" << (i+1) << "]" << endl;
				AttributeList *parentlist=list;
				AttributeList *list=array[i];
				Attribute *MultienergyAcquisitionDescription = (*list)[TagFromName(MultienergyAcquisitionDescription)];
				if (MultienergyAcquisitionDescription) MultienergyAcquisitionDescription->setUsed();
				if (! verifyType3
						(MultienergyAcquisitionDescription,
						"MultienergyCTImage","MultienergyAcquisitionDescription",
						verbose,newformat,log,dict,
									list, 
						0,0)) success=false;
				if (verbose)
					log << "MultienergyCTImage success after verifying MultienergyAcquisitionDescription " << (success ? "success" : "failure") << endl;

				if (!Macro_MultienergyCTXRaySourceMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying MultienergyCTXRaySourceMacro " << (success ? "success" : "failure") << endl;
				if (!Macro_MultienergyCTXRayDetectorMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying MultienergyCTXRayDetectorMacro " << (success ? "success" : "failure") << endl;
				if (!Macro_MultienergyCTPathMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying MultienergyCTPathMacro " << (success ? "success" : "failure") << endl;
				if (!Macro_CTExposureMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying CTExposureMacro " << (success ? "success" : "failure") << endl;
				if (!Macro_CTXRayDetailsMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying CTXRayDetailsMacro " << (success ? "success" : "failure") << endl;
				if (!Macro_CTAcquisitionDetailsMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying CTAcquisitionDetailsMacro " << (success ? "success" : "failure") << endl;
				if (!Macro_CTGeometryMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

				if (verbose)
					log << "MultienergyCTImage success after verifying CTGeometryMacro " << (success ? "success" : "failure") << endl;
			}
		}
	}
	if (!Macro_MultienergyCTProcessingMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "MultienergyCTImage success after verifying MultienergyCTProcessingMacro " << (success ? "success" : "failure") << endl;
	if (!Macro_MultienergyCTCharacteristicsMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

	if (verbose)
		log << "MultienergyCTImage success after verifying MultienergyCTCharacteristicsMacro " << (success ? "success" : "failure") << endl;
	return success;
}

