		if (ImagerPixelSpacing && !ImagerPixelSpacing->verifyNotZero(
			verbose,newformat,log,dict,-1,false)) success=false;

	if (!Macro_BasicPixelSpacingCalibrationMacro(list,ie).verify(list,parentlist,rootlist,verbose,newformat,allpffgitems,log,dict)) success=false;

