				Attribute *RecommendedDisplayFrameRateInFloat = (*list)[TagFromName(RecommendedDisplayFrameRateInFloat)];
				if (RecommendedDisplayFrameRateInFloat) RecommendedDisplayFrameRateInFloat->setUsed();
